$db=Core\DbPdo::conn();$transactions=$db->query("SELECT id FROM ledger_transactions WHERE deleted_at IS NULL ORDER BY id LIMIT 3")->fetchAll(PDO::FETCH_COLUMN)?:[];if(count($transactions)<3)throw new RuntimeException('Cardinality Fixture에는 활성 거래 3건이 필요합니다.');$model=new EvidenceLinkModel($db);$db->beginTransaction();try{$multi='fixture-payroll-'.bin2hex(random_bytes(4));foreach($transactions as$transaction)$model->replaceTransactionEvidences($transaction,[['import_type'=>'PAYROLL_REPORT','evidence_id'=>$multi]]);$multiCount=count($model->activeTransactionsForEvidence('PAYROLL_REPORT',$multi));$model->replaceTransactionEvidences($transactions[1],[['import_type'=>'PAYROLL_REPORT','evidence_id'=>$multi]]);$multiIdempotent=count($model->activeTransactionsForEvidence('PAYROLL_REPORT',$multi));$single='fixture-tax-'.bin2hex(random_bytes(4));$model->replaceTransactionEvidences($transactions[0],[['import_type'=>'TAX_INVOICE','evidence_id'=>$single]]);$singleBlocked=false;try{$model->replaceTransactionEvidences($transactions[1],[['import_type'=>'TAX_INVOICE','evidence_id'=>$single]]);}catch(RuntimeException){$singleBlocked=true;}$db->rollBack();$result=['multi_count'=>$multiCount,'multi_idempotent_count'=>$multiIdempotent,'single_blocked'=>$singleBlocked,'fixture_residue'=>(int)$db->query("SELECT COUNT(*) FROM ledger_evidence_links WHERE evidence_id LIKE 'fixture-%'")->fetchColumn()];$result['success']=$multiCount===3&&$multiIdempotent===3&&$singleBlocked&&$result['fixture_residue']===0;echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;exit($result['success']?0:1);}catch(Throwable$e){if($db->inTransaction())$db->rollBack();throw$e;}
